from gen import *
W='    on _w(id: String) { acct.set(id, 99) return 1 }\n'
case("a01_ufcs_helper", '    on pure(id) { return id._w() }\n'+W)
case("a02_ufcs_signal", '    on pure(id) { return id.bump() }\n')
case("a03_method_transition", '    on pure(id) { id.transition("paid") return 1 }\n')
case("a04_dead_local_shadow", '    on pure(id) { if id == "zzz" { let _w = 1 } return _w(id) }\n'+W)
case("a05_lambda_param_shadow", '    on pure(id) { let xs = map(list(1), _w => 0) return _w(id) }\n'+W)
case("a06_pipe_helper", '    on pure(id) { return id |> _w }\n'+W)
case("a07_pipe_call", '    on pure(id) { return id |> _w() }\n'+W)
case("a08_map_byname", '    on pure(id) { let r = map(list(id), _w) return 1 }\n'+W)
case("a09_map_signal_byname", '    on pure(id) { let r = map(list(id), bump) return 1 }\n')
case("a10_hole_prop", '    on pure(id) [hole] { acct.set(id, 99) return 1 }\n')
case("a11_require_msg", '    on pure(id) { require id == "zzz" else Bad "x {bump(id)}" return 1 }\n', tests=['assert_fails pure("k")','assert peek("k") == 0'])
case("a12_helper_param_named_slot", '    on pure(id) { return _w2(id) }\n    on _w2(acct: String) { acct.set(acct, 99) return 1 }\n')
case("a13_trans_lambda", '    on pure(id) { let r = map(list(id), x => transition(x, "paid")) return 1 }\n')
case("a14_trans_match", '    on pure(id) { let r = match id { "zzz" => 0, _ => transition(id, "paid") } return 1 }\n')
case("a15_trans_interp", '    on pure(id) { let r = "{transition(id, "paid")}" return 1 }\n')
case("a16_trans_try", '    on pure(id) { let r = try { transition(id, "paid") } return 1 }\n')
case("a17_emit_helper", '    on pure(id) { emit _w(id) return 1 }\n'+W, face="")
case("a18_nested_interp", '    on pure(id) { let r = "{"a{bump(id)}"}" return 1 }\n')
case("a19_interp_lambda", '    on pure(id) { let r = map(list(id), x => "v{bump(x)}") return 1 }\n')
case("a20_for_var_shadow", '    on pure(id) { for _w in list() { } return _w(id) }\n'+W)
